#!/bin/bash
set -eo pipefail
set -C
umask 077
printf '%s\n' 'channel=kalmannet-daily-perbasin sequence=73 purpose=single-shared-card-eighteen-input-precheck-only'
task_root=/data1/home/sunyiq/kalmannet_daily_camels_per_basin_21_development_20260908
task_request=$task_root/runtime/precheck_seq73
task_workspace=$task_root/deployment_6b67c6617c2a/workspace
for task_path in /data1 /data1/home /data1/home/sunyiq "$task_root" "$task_root/runtime" "$task_request" "$task_root/prechecks" "$task_root/deployment_6b67c6617c2a" "$task_workspace"; do
  [[ -d "$task_path" && ! -L "$task_path" && "$(readlink -f -- "$task_path")" == "$task_path" ]] || exit 81
done
[[ ! -e "$task_root/prechecks/precheck_seq73" && ! -L "$task_root/prechecks/precheck_seq73" ]] || exit 82
[[ ! -e "$task_request/submission_seq73.attempt" && ! -L "$task_request/submission_seq73.attempt" ]] || exit 83
# Original admission timestamps are historical; the live gate below is current.
(
  cd -- "$task_request"
  sha256sum --check --strict - <<'KNET_ACCEPTED_OPERATIONAL_HASHES'
e699271adab73b959ec316fb646c1af3ed0223b4638f14aa6a785d40ab34fef1  build_precheck_candidate.py
a4d0e20fee16f4ad191a63286c941dd8c882afa7510e1782b91424e503be08c4  precheck_worker.py
9f7a76d3f3ea19fef9fdd97c2f84f9981865672c644e7d9d775c708a47f371da  resource_bind.py
e0167b4814daf19f84ee0e6edcb2e405aba6861848791616027b946bf56f7f3b  precheck.slurm
6a54d7bbf5e59f643d348b4b0f96cb11695d06861328d3b0d3c17de2118be792  precheck.sh
34b9ec0a16a85b8b54138880d53848603c9af33c3a94f6d143fe6a8477702aea  request.json
e5a82d12e4230363496b4249666ab586c7ed2083c9e2d4e2658919827d8f656a  candidate-files.json
KNET_ACCEPTED_OPERATIONAL_HASHES
)
base64 --decode > "$task_request/admission_seq73_livecheck.json" <<'KNET_EXTERNAL_ADMISSION'

KNET_EXTERNAL_ADMISSION
printf '%s  %s\n' 'a874dfd214bde64f97fba11d46b8cdf29bd7638e5d54a07d00e079f2518a0271' "$task_request/admission_seq73_livecheck.json" | sha256sum --check --strict -
export PYTHONDONTWRITEBYTECODE=1
/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -I -B - "$task_workspace/scripts/daily_camels_development_guard.py" "$task_request/admission_seq73_livecheck.json" <<'KNET_REPLAY_ONLY_STDLIB'
import base64, hashlib, importlib.util, json, pathlib, sys, time
source = pathlib.Path(sys.argv[1])
assert hashlib.sha256(source.read_bytes()).hexdigest() == '85a7d4b3c16dd9a595f4d47d9f20c441644ab92b029b660f30abea67d57523c1'
spec = importlib.util.spec_from_file_location('accepted_guard', source)
guard = importlib.util.module_from_spec(spec)
spec.loader.exec_module(guard)
payload = guard.strict_json(pathlib.Path(sys.argv[2]).read_bytes())
guard.exact(payload, 'events artifacts_base64 authorization_sha256 independently_accepted_sha256 configuration_manifest_sha256 resource_policy_sha256 submission_deadline_seconds', 'controller admission')
# Replay keeps the original event/observation times and immutable reservation.
assert type(payload['submission_deadline_seconds']) is int
state = guard.replay(payload['events'], artifacts={key: base64.b64decode(value, validate=True) for key, value in payload['artifacts_base64'].items()}, authorization_sha256=payload['authorization_sha256'], independently_accepted_sha256=set(payload['independently_accepted_sha256']), configuration_manifest_sha256=payload['configuration_manifest_sha256'], resource_policy_sha256=payload['resource_policy_sha256'])
assert state['authorization_status'] == 'AUTHORIZED' and not state['paused']
assert state['submissions'] == 0 and state['precheck_attempts'] == 1
assert state['reserved'] == {'precheck_gpu_seconds':1800,'training_gpu_seconds':0,'report_core_seconds':0}
assert state['actual'] == {'precheck_gpu_seconds':0,'training_gpu_seconds':0,'report_core_seconds':0}
assert len(state['requests']) == 1
request = state['requests']['precheck_seq73']
assert request['kind'] == 'precheck' and request['sequence'] == 73 and request['job_id'] is None
assert request['run_directory'] == '/data1/home/sunyiq/kalmannet_daily_camels_per_basin_21_development_20260908/prechecks/precheck_seq73'
print(json.dumps({'guard_admission':'PASS','reserved_gpu_seconds':1800,'compute_submissions':0}), flush=True)
KNET_REPLAY_ONLY_STDLIB
base64 --decode > "$task_request/precheck_live_submission_check_seq73.py" <<'KNET_LIVE_CHECKER'

KNET_LIVE_CHECKER
printf '%s  %s\n' '639299401b6015185f7f40d2ea50658911ad42f6e3900f8eaf034b8bf1e54619' "$task_request/precheck_live_submission_check_seq73.py" | sha256sum --check --strict -
task_observed=$(/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -I -B "$task_request/precheck_live_submission_check_seq73.py")
[[ "$task_observed" =~ ^[0-9]+$ ]] || exit 85
# Recheck all seven frozen payloads after potentially slow live queries.
(
  cd -- "$task_request"
  sha256sum --check --strict - <<'KNET_ACCEPTED_OPERATIONAL_HASHES'
e699271adab73b959ec316fb646c1af3ed0223b4638f14aa6a785d40ab34fef1  build_precheck_candidate.py
a4d0e20fee16f4ad191a63286c941dd8c882afa7510e1782b91424e503be08c4  precheck_worker.py
9f7a76d3f3ea19fef9fdd97c2f84f9981865672c644e7d9d775c708a47f371da  resource_bind.py
e0167b4814daf19f84ee0e6edcb2e405aba6861848791616027b946bf56f7f3b  precheck.slurm
6a54d7bbf5e59f643d348b4b0f96cb11695d06861328d3b0d3c17de2118be792  precheck.sh
34b9ec0a16a85b8b54138880d53848603c9af33c3a94f6d143fe6a8477702aea  request.json
e5a82d12e4230363496b4249666ab586c7ed2083c9e2d4e2658919827d8f656a  candidate-files.json
KNET_ACCEPTED_OPERATIONAL_HASHES
)
/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -I -B - "$task_request/precheck_live_submission_check_seq73.py" "$task_observed" <<'KNET_FINAL_LIVE_GATE'
import hashlib, importlib.util, pathlib, sys, time
source = pathlib.Path(sys.argv[1])
assert hashlib.sha256(source.read_bytes()).hexdigest() == '639299401b6015185f7f40d2ea50658911ad42f6e3900f8eaf034b8bf1e54619'
spec = importlib.util.spec_from_file_location('live_check', source)
live = importlib.util.module_from_spec(spec)
spec.loader.exec_module(live)
root = pathlib.Path(live.ROOT)
state, authority = live.replay_admission(root / live.DEPLOYMENT / 'workspace/scripts/daily_camels_development_guard.py', root / live.REQUEST / 'admission_seq73_livecheck.json')
live.check_paths(root)
observed, now = int(sys.argv[2]), int(time.time())
assert 0 <= now-observed <= 300
live.current_authority(authority, now)
print('LIVE_GATE_PASS observation_seconds=' + str(observed) + ' current_seconds=' + str(now), flush=True)
KNET_FINAL_LIVE_GATE
task_now=$(date +%s)
[[ "$task_now" =~ ^[0-9]+$ && "$task_now" -ge "$task_observed" && "$((task_now-task_observed))" -le 300 && "$task_now" -ge 1788878005 && "$task_now" -le 1789482805 ]] || { printf '%s\n' 'LIVE_FRESHNESS_OR_AUTHORIZATION_STOP_NO_SUBMISSION'; exit 85; }
date -u '+submission_attempt_utc=%Y-%m-%dT%H:%M:%SZ' > "$task_request/submission_seq73.attempt"
if sbatch "$task_request/precheck.slurm" > "$task_request/submission_seq73.stdout" 2> "$task_request/submission_seq73.stderr"; then task_submit_rc=0; else task_submit_rc=$?; fi
printf 'SBATCH_COMMAND_EXIT=%s\n' "$task_submit_rc"
cat -- "$task_request/submission_seq73.stdout"
cat -- "$task_request/submission_seq73.stderr"
sha256sum -- "$task_request/submission_seq73.attempt" "$task_request/submission_seq73.stdout" "$task_request/submission_seq73.stderr"
task_receipts=$(awk '/^Submitted batch job [1-9][0-9]*$/ {count++} END {print count+0}' "$task_request/submission_seq73.stdout")
[[ "$task_submit_rc" == 0 && "$task_receipts" == 1 ]] || { printf '%s\n' 'SUBMISSION_UNCERTAIN_STOP_NO_RETRY'; exit 86; }
task_job=$(awk '/^Submitted batch job [1-9][0-9]*$/ {print $4}' "$task_request/submission_seq73.stdout")
printf 'CONFIRMED_PRECHECK_JOB_ID=%s\n' "$task_job"
if scontrol show job -dd "$task_job"; then :; else printf '%s\n' 'POST_SUBMISSION_METADATA_UNAVAILABLE_USE_ACCOUNTING'; fi
printf '%s\n' 'SUBMIT_COMPLETE training_submissions=0 precheck_submissions=1 automatic_resubmit=0'
